import csv, json, os
from datetime import datetime

DATE_FORMATS = ["%Y-%m-%d", "%d-%b-%Y", "%m/%d/%Y"]

def parse_date(s):
    for f in DATE_FORMATS:
        try:
            return datetime.strptime(s.strip(), f)
        except ValueError:
            pass
    raise ValueError(f"Unparseable date: {s}")

def parse_updated(s):
    return datetime.strptime(s.strip(), "%Y-%m-%dT%H:%M:%S")

# 1. Load & parse_dates
orders = []
with open("data/orders.csv", newline="") as f:
    for row in csv.DictReader(f):
        od = parse_date(row["order_date"])
        ua = parse_updated(row["updated_at"])
        orders.append({
            "order_id": row["order_id"],
            "customer_id": row["customer_id"],
            "status": row["status"],
            "order_date": od,
            "updated_at": ua,
            "amount": float(row["amount"]),
            "month": od.strftime("%Y-%m"),
        })

# 2. filter_cancelled
orders = [o for o in orders if o["status"] != "cancelled"]

# 3. deduplicate_latest (keep latest updated_at per order_id)
latest = {}
for o in orders:
    key = o["order_id"]
    if key not in latest or o["updated_at"] > latest[key]["updated_at"]:
        latest[key] = o
orders = list(latest.values())

# 4. join_customers
with open("data/customers.json") as f:
    customers = {c["customer_id"]: c for c in json.load(f)}
for o in orders:
    o["segment"] = customers[o["customer_id"]]["segment"]

# 5. apply_adjustments
adjustments = {}
with open("data/adjustments.csv", newline="") as f:
    for row in csv.DictReader(f):
        adjustments[row["order_id"]] = float(row["adjustment"])
for o in orders:
    if o["order_id"] in adjustments:
        o["amount"] += adjustments[o["order_id"]]

# Group by month, segment
groups = {}
for o in orders:
    key = (o["month"], o["segment"])
    g = groups.setdefault(key, {"month": o["month"], "segment": o["segment"], "order_count": 0, "total_amount": 0.0})
    g["order_count"] += 1
    g["total_amount"] += o["amount"]

result = []
for key in sorted(groups.keys()):
    g = groups[key]
    result.append({
        "month": g["month"],
        "segment": g["segment"],
        "order_count": g["order_count"],
        "total_amount": round(g["total_amount"], 2),
    })

os.makedirs("outputs", exist_ok=True)
with open("outputs/report.json", "w") as f:
    json.dump(result, f, indent=2)

print(json.dumps(result, indent=2))

