        region = str(row["region"])
        if region not in summary:
            summary[region] = {"region": region, "row_count": 0, "total_amount": 0.0}
        summary[region]["row_count"] = int(summary[region]["row_count"]) + 1
        summary[region]["total_amount"] = round(
