import csv
import json
import os
from datetime import datetime

def parse_date(s):
    s = s.strip()
    for fmt in ("%m/%d/%Y", "%Y-%m-%d", "%d-%b-%Y"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unparseable date: {s}")

# Load orders
with open("data/orders.csv", newline="") as f:
    reader = csv.DictReader(f)
    orders = list(reader)

# 1. parse_dates
for o in orders:
    o["order_date_dt"] = parse_date(o["order_date"])
    o["updated_at_dt"] = datetime.fromisoformat(o["updated_at"])
    o["amount_f"] = float(o["amount"])

# 2. filter_cancelled
orders = [o for o in orders if o["status"] != "cancelled"]

# 3. deduplicate_latest (latest updated_at per order_id)
latest = {}
for o in orders:
    oid = o["order_id"]
    if oid not in latest or o["updated_at_dt"] > latest[oid]["updated_at_dt"]:
        latest[oid] = o
orders = list(latest.values())

# 4. join_customers
with open("data/customers.json") as f:
    customers = {c["customer_id"]: c for c in json.load(f)}
for o in orders:
    o["segment"] = customers[o["customer_id"]]["segment"]

# Group by month and segment
groups = {}
for o in orders:
    month = o["order_date_dt"].strftime("%Y-%m")
    seg = o["segment"]
    key = (month, seg)
    if key not in groups:
        groups[key] = {"month": month, "segment": seg, "order_count": 0, "total_amount": 0.0}
    groups[key]["order_count"] += 1
    groups[key]["total_amount"] += o["amount_f"]

rows = []
for key in sorted(groups.keys()):
    g = groups[key]
    rows.append({
        "month": g["month"],
        "segment": g["segment"],
        "order_count": g["order_count"],
        "total_amount": round(g["total_amount"], 2),
    })

os.makedirs("outputs", exist_ok=True)
with open("outputs/report.json", "w") as f:
    json.dump(rows, f, indent=2)

print(json.dumps(rows, indent=2))

