import csv, json
from datetime import datetime
from collections import defaultdict

DATE_FORMATS = ["%d-%b-%Y", "%Y-%m-%d", "%m/%d/%Y"]

def parse_order_date(s):
    s = s.strip()
    for f in DATE_FORMATS:
        try:
            return datetime.strptime(s, f)
        except ValueError:
            continue
    raise ValueError(f"Unparseable date: {s}")

def parse_updated(s):
    return datetime.fromisoformat(s.strip())

# 1. parse_dates
orders = []
with open("data/orders.csv", newline="") as fh:
    for row in csv.DictReader(fh):
        od = parse_order_date(row["order_date"])
        ua = parse_updated(row["updated_at"])
        orders.append({
            "order_id": row["order_id"],
            "customer_id": row["customer_id"],
            "status": row["status"],
            "order_date": od,
            "updated_at": ua,
            "amount": float(row["amount"]),
            "month": od.strftime("%Y-%m"),
        })

# 2. filter_cancelled
orders = [o for o in orders if o["status"] != "cancelled"]

# 3. deduplicate_latest (keep latest updated_at per order_id)
latest = {}
for o in orders:
    cur = latest.get(o["order_id"])
    if cur is None or o["updated_at"] > cur["updated_at"]:
        latest[o["order_id"]] = o
orders = list(latest.values())

# 4. join_customers
with open("data/customers.json") as fh:
    customers = {c["customer_id"]: c for c in json.load(fh)}
for o in orders:
    o["segment"] = customers[o["customer_id"]]["segment"]

# 5. apply_adjustments
adj = {}
with open("data/adjustments.csv", newline="") as fh:
    for row in csv.DictReader(fh):
        adj[row["order_id"]] = float(row["adjustment"])
for o in orders:
    if o["order_id"] in adj:
        o["amount"] += adj[o["order_id"]]

# group by month, segment
groups = defaultdict(lambda: {"order_count": 0, "total_amount": 0.0})
for o in orders:
    key = (o["month"], o["segment"])
    g = groups[key]
    g["order_count"] += 1
    g["total_amount"] += o["amount"]

result = []
for (month, segment) in sorted(groups.keys()):
    g = groups[(month, segment)]
    result.append({
        "month": month,
        "segment": segment,
        "order_count": g["order_count"],
        "total_amount": round(g["total_amount"], 2),
    })

import os
os.makedirs("outputs", exist_ok=True)
with open("outputs/report.json", "w") as fh:
    json.dump(result, fh, indent=2)

print(json.dumps(result, indent=2))

