import csv, json, os
from datetime import datetime

rows = []
with open('data/orders.csv', newline='') as f:
    for r in csv.DictReader(f):
        rows.append(r)

# parse_dates
def parse_date(s):
    s = s.strip()
    for fmt in ('%m/%d/%Y', '%Y-%m-%d', '%d-%b-%Y'):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"unparseable date: {s}")

for r in rows:
    r['_date'] = parse_date(r['order_date'])
    r['_updated'] = datetime.fromisoformat(r['updated_at'])
    r['month'] = r['_date'].strftime('%Y-%m')

# filter_cancelled
rows = [r for r in rows if r['status'] != 'cancelled']

# deduplicate_latest by order_id, keep latest updated_at
latest = {}
for r in rows:
    oid = r['order_id']
    if oid not in latest or r['_updated'] > latest[oid]['_updated']:
        latest[oid] = r
rows = list(latest.values())

# group by month
groups = {}
for r in rows:
    g = groups.setdefault(r['month'], {'month': r['month'], 'order_count': 0, 'total_amount': 0.0})
    g['order_count'] += 1
    g['total_amount'] += float(r['amount'])

out = []
for m in sorted(groups.keys()):
    g = groups[m]
    out.append({'month': g['month'], 'order_count': g['order_count'], 'total_amount': round(g['total_amount'], 2)})

os.makedirs('outputs', exist_ok=True)
with open('outputs/report.json', 'w') as f:
    json.dump(out, f, indent=2)

print(json.dumps(out, indent=2))

