import json, csv
from datetime import datetime
from collections import defaultdict

events = json.load(open("data/events.json"))

accounts = {}
with open("data/accounts.csv") as f:
    for row in csv.DictReader(f):
        accounts[row["account_id"]] = row["region"].strip().lower()

fmts = ["%m/%d/%Y %H:%M", "%Y/%m/%d %H:%M", "%Y-%m-%d %H:%M"]

def parse_ts(s):
    for f in fmts:
        try:
            return datetime.strptime(s, f)
        except ValueError:
            continue
    raise ValueError(s)

rows = []
for e in events:
    dt = parse_ts(e["booked_at"])
    status = e["status"].strip().lower()
    if status != "posted":
        continue  # filter pending
    region = accounts[e["account_id"]]
    etype = e["event_type"].strip().lower()
    amt = e["amount"]
    if etype == "refund":
        amt = -amt
    elif etype == "sale":
        amt = amt
    else:
        # treat unknown as sale
        amt = amt
    iso = dt.isocalendar()
    week = f"{iso[0]:04d}-W{iso[1]:02d}"
    rows.append((week, region, amt))

agg = defaultdict(lambda: {"event_count": 0, "net_amount": 0.0})
for week, region, amt in rows:
    agg[(week, region)]["event_count"] += 1
    agg[(week, region)]["net_amount"] += amt

out = []
for (week, region), v in agg.items():
    out.append({
        "week": week,
        "region": region,
        "event_count": v["event_count"],
        "net_amount": round(v["net_amount"], 2),
    })

out.sort(key=lambda r: (r["week"], r["region"]))

import os
os.makedirs("outputs", exist_ok=True)
json.dump(out, open("outputs/weekly_rollup.json", "w"), indent=2)
print(json.dumps(out, indent=2))

