import csv
import json
from datetime import datetime

def parse_date(s):
    s = s.strip()
    fmts = [
        "%Y-%m-%d",
        "%m/%d/%Y",
        "%d-%b-%Y",
        "%Y/%m/%d",
    ]
    for f in fmts:
        try:
            return datetime.strptime(s, f)
        except ValueError:
            pass
    raise ValueError(f"Unparseable date: {s}")

def parse_updated(s):
    return datetime.fromisoformat(s.strip())

# Load customers
with open("data/customers.json") as f:
    customers = {c["customer_id"]: c for c in json.load(f)}

# Load orders
rows = []
with open("data/orders.csv", newline="") as f:
    for r in csv.DictReader(f):
        r["_order_dt"] = parse_date(r["order_date"])
        r["_updated_dt"] = parse_updated(r["updated_at"])
        r["amount"] = float(r["amount"])
        rows.append(r)

# filter_cancelled
rows = [r for r in rows if r["status"] != "cancelled"]

# deduplicate_latest: keep latest updated_at per order_id
latest = {}
for r in rows:
    key = r["order_id"]
    if key not in latest or r["_updated_dt"] > latest[key]["_updated_dt"]:
        latest[key] = r
rows = list(latest.values())

# join_customers + group by month and segment
groups = {}
for r in rows:
    cust = customers.get(r["customer_id"])
    if cust is None:
        continue
    segment = cust["segment"]
    month = r["_order_dt"].strftime("%Y-%m")
    g = (month, segment)
    if g not in groups:
        groups[g] = {"order_count": 0, "total_amount": 0.0}
    groups[g]["order_count"] += 1
    groups[g]["total_amount"] += r["amount"]

# sort lexicographically by (month, segment)
result = []
for (month, segment) in sorted(groups.keys()):
    v = groups[(month, segment)]
    result.append({
        "month": month,
        "segment": segment,
        "order_count": v["order_count"],
        "total_amount": round(v["total_amount"], 2),
    })

import os
os.makedirs("outputs", exist_ok=True)
with open("outputs/report.json", "w") as f:
    json.dump(result, f, indent=2)

print(json.dumps(result, indent=2))

