import csv, json
from datetime import datetime
from collections import defaultdict

def parse_date(s):
    s = s.strip()
    for fmt in ("%Y-%m-%d", "%d-%b-%Y", "%m/%d/%Y"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unparseable date: {s}")

# Load orders
orders = []
with open("data/orders.csv", newline="") as f:
    for row in csv.DictReader(f):
        row["order_date_dt"] = parse_date(row["order_date"])
        row["updated_at_dt"] = datetime.fromisoformat(row["updated_at"])
        row["amount"] = float(row["amount"])
        orders.append(row)

# filter_cancelled
orders = [o for o in orders if o["status"] != "cancelled"]

# deduplicate_latest: keep latest updated_at per order_id
latest = {}
for o in orders:
    oid = o["order_id"]
    if oid not in latest or o["updated_at_dt"] > latest[oid]["updated_at_dt"]:
        latest[oid] = o
orders = list(latest.values())

# join_customers
cust_map = {}
with open("data/customers.json") as f:
    for c in json.load(f):
        cust_map[c["customer_id"]] = c
for o in orders:
    o["segment"] = cust_map[o["customer_id"]]["segment"]

# apply_adjustments
adj_map = {}
with open("data/adjustments.csv", newline="") as f:
    for row in csv.DictReader(f):
        adj_map[row["order_id"]] = float(row["adjustment"])
for o in orders:
    if o["order_id"] in adj_map:
        o["amount"] += adj_map[o["order_id"]]

# group by month and segment
groups = defaultdict(lambda: {"order_count": 0, "total_amount": 0.0})
for o in orders:
    month = o["order_date_dt"].strftime("%Y-%m")
    seg = o["segment"]
    key = (month, seg)
    groups[key]["order_count"] += 1
    groups[key]["total_amount"] += o["amount"]

result = []
for (month, seg) in sorted(groups.keys()):
    g = groups[(month, seg)]
    result.append({
        "month": month,
        "segment": seg,
        "order_count": g["order_count"],
        "total_amount": round(g["total_amount"], 2),
    })

import os
os.makedirs("outputs", exist_ok=True)
with open("outputs/report.json", "w") as f:
    json.dump(result, f, indent=2)

print(json.dumps(result, indent=2))

