import csv, json, os
from datetime import datetime

def parse_date(s):
    s = s.strip()
    for fmt in ("%Y-%m-%d", "%d-%b-%Y", "%m/%d/%Y"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    raise ValueError("bad date: " + s)

# Load orders
rows = []
with open("data/orders.csv") as f:
    for r in csv.DictReader(f):
        r["amount"] = float(r["amount"])
        r["_order_date"] = parse_date(r["order_date"])
        r["_updated_at"] = datetime.strptime(r["updated_at"], "%Y-%m-%dT%H:%M:%S")
        rows.append(r)

# 1 parse_dates done

# 2 filter_cancelled
rows = [r for r in rows if r["status"] != "cancelled"]

# 3 deduplicate_latest by order_id, keep latest updated_at
latest = {}
for r in rows:
    oid = r["order_id"]
    if oid not in latest or r["_updated_at"] > latest[oid]["_updated_at"]:
        latest[oid] = r
rows = list(latest.values())

# 4 join_customers
cust = {}
with open("data/customers.json") as f:
    for c in json.load(f):
        cust[c["customer_id"]] = c
for r in rows:
    r["segment"] = cust[r["customer_id"]]["segment"]
    r["month"] = r["_order_date"].strftime("%Y-%m")

# 5 apply_adjustments
adj = {}
with open("data/adjustments.csv") as f:
    for a in csv.DictReader(f):
        adj[a["order_id"]] = float(a["adjustment"])
for r in rows:
    if r["order_id"] in adj:
        r["amount"] += adj[r["order_id"]]

# group by month, segment
groups = {}
for r in rows:
    key = (r["month"], r["segment"])
    g = groups.setdefault(key, {"month": r["month"], "segment": r["segment"], "order_count": 0, "total_amount": 0.0})
    g["order_count"] += 1
    g["total_amount"] += r["amount"]

out = []
for key in sorted(groups.keys()):
    g = groups[key]
    out.append({
        "month": g["month"],
        "segment": g["segment"],
        "order_count": g["order_count"],
        "total_amount": round(g["total_amount"], 2),
    })

os.makedirs("outputs", exist_ok=True)
with open("outputs/report.json", "w") as f:
    json.dump(out, f, indent=2)

print(json.dumps(out, indent=2))

