def build_region_report(rows: list[dict[str, object]]) -> list[dict[str, object]]:
    summary: dict[str, dict[str, object]] = {}
    for row in rows:
        if row["status"] == "cancelled":
            continue
        region = str(row["region"])
        if region not in summary:
