import csv
import json
from datetime import datetime
from collections import defaultdict

# --- 1. parse_dates ---
def parse_order_date(s):
    s = s.strip()
    for fmt in ("%m/%d/%Y", "%Y-%m-%d", "%d-%b-%Y"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unparseable order_date: {s!r}")

def parse_updated_at(s):
    return datetime.fromisoformat(s.strip())

orders = []
with open("data/orders.csv", newline="") as f:
    for row in csv.DictReader(f):
        od = parse_order_date(row["order_date"])
        ua = parse_updated_at(row["updated_at"])
        row["order_date_dt"] = od
        row["updated_at_dt"] = ua
        row["amount_f"] = float(row["amount"])
        orders.append(row)

# --- 2. filter_cancelled ---
orders = [o for o in orders if o["status"] != "cancelled"]

# --- 3. deduplicate_latest (keep latest updated_at per order_id) ---
latest = {}
