import csv
import json
from datetime import datetime

rows = []
with open('data/orders.csv', newline='') as f:
    for r in csv.DictReader(f):
        rows.append(r)

# parse_dates: parse order_date into month YYYY-MM
def parse_date(s):
    s = s.strip()
    fmts = ['%Y-%m-%d', '%d-%b-%Y', '%m/%d/%Y']
    for fmt in fmts:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"unparseable date: {s}")

for r in rows:
    dt = parse_date(r['order_date'])
    r['month'] = dt.strftime('%Y-%m')
    r['updated_at_dt'] = datetime.strptime(r['updated_at'], '%Y-%m-%dT%H:%M:%S')
    r['amount_f'] = float(r['amount'])

# filter_cancelled
rows = [r for r in rows if r['status'] != 'cancelled']

# deduplicate_latest: keep latest updated_at per order_id
latest = {}
for r in rows:
    oid = r['order_id']
    if oid not in latest or r['updated_at_dt'] > latest[oid]['updated_at_dt']:
        latest[oid] = r

dedup = list(latest.values())

# group by month
groups = {}
for r in dedup:
    m = r['month']
    if m not in groups:
        groups[m] = {'order_count': 0, 'total_amount': 0.0}
    groups[m]['order_count'] += 1
    groups[m]['total_amount'] += r['amount_f']

result = []
for m in sorted(groups.keys()):
    result.append({
        'month': m,
        'order_count': groups[m]['order_count'],
        'total_amount': round(groups[m]['total_amount'], 2)
    })

import os
os.makedirs('outputs', exist_ok=True)
with open('outputs/report.json', 'w') as f:
    json.dump(result, f, indent=2)

print(json.dumps(result, indent=2))

