import json
import csv
import os

# 1. normalize_channels: read store_channels.csv, strip whitespace + lowercase
channels = {}
with open('data/store_channels.csv', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        norm = row['channel'].strip().lower()
        channels[row['store_id'].strip()] = norm

# 2. filter_cancelled: load orders, drop cancelled, attach channel
with open('data/orders.json') as f:
    orders = json.load(f)

def norm_status(s):
    return s.strip().lower()

kept = []
for o in orders:
    if norm_status(o['status']) == 'cancelled':
        continue
    o = dict(o)
    o['channel'] = channels[o['store_id']]
    o['status'] = norm_status(o['status'])
    kept.append(o)

# 3. aggregate_status_counts
agg = {}
for o in kept:
    ch = o['channel']
    if ch not in agg:
        agg[ch] = {'completed_orders': 0, 'processing_orders': 0, 'total_amount': 0.0}
    if o['status'] == 'completed':
        agg[ch]['completed_orders'] += 1
    elif o['status'] == 'processing':
        agg[ch]['processing_orders'] += 1
    agg[ch]['total_amount'] += o['amount']

