import csv
import json
import os
from datetime import datetime

os.makedirs("outputs", exist_ok=True)

# 1. parse orders
with open("data/orders.csv", newline="") as f:
    orders = list(csv.DictReader(f))

date_formats = [
    "%d-%b-%Y",   # 08-Feb-2024
    "%m/%d/%Y",   # 01/15/2024
    "%Y-%m-%d",   # 2024-01-21
]

def parse_order_date(s):
    for fmt in date_formats:
        try:
            return datetime.strptime(s.strip(), fmt)
        except ValueError:
            pass
    raise ValueError(f"Unknown date format: {s}")

# parse_dates
for o in orders:
    d = parse_order_date(o["order_date"])
    o["order_date_dt"] = d
    o["month"] = d.strftime("%Y-%m")
    o["updated_at_dt"] = datetime.fromisoformat(o["updated_at"])

# 2. filter_cancelled
orders = [o for o in orders if o["status"] != "cancelled"]

# 3. deduplicate_latest (latest updated_at per order_id)
latest = {}
for o in orders:
    oid = o["order_id"]
    if oid not in latest or o["updated_at_dt"] > latest[oid]["updated_at_dt"]:
        latest[oid] = o
orders = list(latest.values())

# 4. join_customers
with open("data/customers.json") as f:
    customers = {c["customer_id"]: c for c in json.load(f)}
for o in orders:
    o["segment"] = customers[o["customer_id"]]["segment"]

# 5. apply_adjustments
with open("data/adjustments.csv", newline="") as f:
    adj = {row["order_id"]: float(row["adjustment"]) for row in csv.DictReader(f)}
for o in orders:
    if o["order_id"] in adj:
        o["amount"] = float(o["amount"]) + adj[o["order_id"]]
    else:
        o["amount"] = float(o["amount"])

# group by month, segment
groups = {}
for o in orders:
    key = (o["month"], o["segment"])
    if key not in groups:
        groups[key] = {"order_count": 0, "total_amount": 0.0}
    groups[key]["order_count"] += 1
    groups[key]["total_amount"] += o["amount"]

rows = []
for key in sorted(groups.keys()):
    month, segment = key
    g = groups[key]
    rows.append({
        "month": month,
        "segment": segment,
        "order_count": g["order_count"],
        "total_amount": round(g["total_amount"], 2),
    })

with open("outputs/report.json", "w") as f:
    json.dump(rows, f, indent=2)

print(json.dumps(rows, indent=2))

