import csv, json, os
from datetime import datetime

# 1. Load orders
orders = []
with open('data/orders.csv', newline='') as f:
    for row in csv.DictReader(f):
        orders.append(row)

# Load customers
with open('data/customers.json') as f:
    customers = json.load(f)
cust_map = {c['customer_id']: c for c in customers}

# Load adjustments
adj_map = {}
with open('data/adjustments.csv', newline='') as f:
    for row in csv.DictReader(f):
        adj_map[row['order_id']] = float(row['adjustment'])

# 1. parse_dates
def parse_date(s):
    s = s.strip()
    for fmt in ('%Y-%m-%d', '%m/%d/%Y', '%d-%b-%Y'):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unknown date format: {s}")

for o in orders:
    o['_order_date'] = parse_date(o['order_date'])
    o['_updated_at'] = datetime.fromisoformat(o['updated_at'])
    o['month'] = o['_order_date'].strftime('%Y-%m')

# 2. filter_cancelled
orders = [o for o in orders if o['status'] != 'cancelled']

# 3. deduplicate_latest (keep latest updated_at per order_id)
latest = {}
for o in orders:
    key = o['order_id']
    if key not in latest or o['_updated_at'] > latest[key]['_updated_at']:
        latest[key] = o
orders = list(latest.values())

# 4. join_customers
for o in orders:
    c = cust_map[o['customer_id']]
    o['segment'] = c['segment']

# 5. apply_adjustments
for o in orders:
    if o['order_id'] in adj_map:
        o['amount'] = float(o['amount']) + adj_map[o['order_id']]
    else:
        o['amount'] = float(o['amount'])

# Group by month, segment
groups = {}
for o in orders:
    key = (o['month'], o['segment'])
    if key not in groups:
        groups[key] = {'order_count': 0, 'total_amount': 0.0}
    groups[key]['order_count'] += 1
    groups[key]['total_amount'] += o['amount']

result = []
for (month, segment) in sorted(groups.keys()):
    result.append({
        'month': month,
        'segment': segment,
        'order_count': groups[(month, segment)]['order_count'],
        'total_amount': round(groups[(month, segment)]['total_amount'], 2),
    })

os.makedirs('outputs', exist_ok=True)
with open('outputs/report.json', 'w') as f:
    json.dump(result, f, indent=2)

print(json.dumps(result, indent=2))

