import json, csv
from datetime import datetime
from collections import defaultdict

def parse_ts(s):
    for fmt in ("%Y-%m-%d %H:%M", "%m/%d/%Y %H:%M", "%Y/%m/%d %H:%M"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"unparsed timestamp: {s}")

with open("data/events.json") as f:
    events = json.load(f)

accts = {}
with open("data/accounts.csv", newline="") as f:
    for row in csv.DictReader(f):
        accts[row["account_id"]] = row["region"].strip().lower()

groups = defaultdict(lambda: {"count": 0, "net": 0.0})
for e in events:
    if e["status"].strip().lower() == "pending":
        continue
    region = accts[e["account_id"]]
    dt = parse_ts(e["booked_at"])
    week = dt.strftime("%G-W%V")
    etype = e["event_type"].strip().lower()
    amt = e["amount"]
    if etype == "refund":
        amt = -amt
    groups[(week, region)]["count"] += 1
    groups[(week, region)]["net"] += amt

rows = []
for (week, region), v in groups.items():
    rows.append({
        "week": week,
        "region": region,
        "event_count": v["count"],
        "net_amount": round(v["net"], 2),
    })

rows.sort(key=lambda r: (r["week"], r["region"]))

import os
os.makedirs("outputs", exist_ok=True)
with open("outputs/weekly_rollup.json", "w") as f:
    json.dump(rows, f, indent=2)

print(json.dumps(rows, indent=2))

