import csv
import json
import os
from datetime import datetime

ORDERS = "data/orders.csv"
CUSTOMERS = "data/customers.json"
ADJUSTMENTS = "data/adjustments.csv"
OUT = "outputs/report.json"

DATE_FORMATS = [
    "%Y-%m-%d",
    "%d-%b-%Y",
    "%m/%d/%Y",
]
DATETIME_FORMATS = [
    "%Y-%m-%dT%H:%M:%S",
]


def parse_date(s):
    for f in DATE_FORMATS:
        try:
            return datetime.strptime(s.strip(), f)
        except ValueError:
            pass
    raise ValueError(f"Cannot parse date: {s}")


def parse_datetime(s):
    for f in DATETIME_FORMATS:
        try:
            return datetime.strptime(s.strip(), f)
        except ValueError:
            pass
    raise ValueError(f"Cannot parse datetime: {s}")


# 1. parse_dates + load orders
rows = []
with open(ORDERS, newline="") as f:
    for r in csv.DictReader(f):
        od = parse_date(r["order_date"])
        ua = parse_datetime(r["updated_at"])
        rows.append({
            "order_id": r["order_id"],
            "customer_id": r["customer_id"],
            "status": r["status"],
            "order_date": od,
            "updated_at": ua,
            "amount": float(r["amount"]),
        })

# 2. filter_cancelled
rows = [r for r in rows if r["status"] != "cancelled"]

# 3. deduplicate_latest: keep latest updated_at per order_id
latest = {}
for r in rows:
    key = r["order_id"]
    if key not in latest or r["updated_at"] > latest[key]["updated_at"]:
        latest[key] = r
rows = list(latest.values())

# 4. join_customers
with open(CUSTOMERS) as f:
    customers = {c["customer_id"]: c for c in json.load(f)}
for r in rows:
    c = customers[r["customer_id"]]
    r["segment"] = c["segment"]

# 5. apply_adjustments
adj = {}
with open(ADJUSTMENTS, newline="") as f:
    for r in csv.DictReader(f):
        adj[r["order_id"]] = float(r["adjustment"])
for r in rows:
    if r["order_id"] in adj:
        r["amount"] += adj[r["order_id"]]

# group by month and segment
groups = {}
for r in rows:
    month = r["order_date"].strftime("%Y-%m")
    key = (month, r["segment"])
    g = groups.setdefault(key, {"month": month, "segment": r["segment"], "order_count": 0, "total_amount": 0.0})
    g["order_count"] += 1
    g["total_amount"] += r["amount"]

out = []
for key in sorted(groups.keys()):
    g = groups[key]
    out.append({
        "month": g["month"],
        "segment": g["segment"],
        "order_count": g["order_count"],
        "total_amount": round(g["total_amount"], 2),
    })

os.makedirs("outputs", exist_ok=True)
with open(OUT, "w") as f:
    json.dump(out, f, indent=2)

print(json.dumps(out, indent=2))

