import json, csv, re
from datetime import datetime

def parse_ts(s):
    s = s.strip()
    fmts = [
        "%m/%d/%Y %H:%M",
        "%Y-%m-%d %H:%M",
        "%Y/%m/%d %H:%M",
    ]
    for f in fmts:
        try:
            return datetime.strptime(s, f)
        except ValueError:
            pass
    raise ValueError(f"Unparseable timestamp: {s}")

with open("data/events.json") as f:
    events = json.load(f)

accounts = {}
with open("data/accounts.csv") as f:
    reader = csv.DictReader(f)
    for row in reader:
        accounts[row["account_id"].strip()] = row["region"].strip().lower()

rows = []
for ev in events:
    if ev["status"].strip().lower() != "posted":
        continue
    dt = parse_ts(ev["booked_at"])
    region = accounts.get(ev["account_id"].strip(), "").strip().lower()
    etype = ev["event_type"].strip().lower()
    amt = float(ev["amount"])
    if etype == "refund":
        amt = -amt
    iso_year, iso_week, _ = dt.isocalendar()
    week = f"{iso_year}-W{iso_week:02d}"
    rows.append((week, region, amt))

agg = {}
