import csv, json, os
from datetime import datetime
from collections import defaultdict

def parse_date(s):
    s = s.strip()
    fmts = ["%Y-%m-%d", "%m/%d/%Y", "%d-%b-%Y", "%d/%m/%Y"]
    for f in fmts:
        try:
            return datetime.strptime(s, f)
        except ValueError:
            pass
    raise ValueError(f"Unknown date format: {s}")

# 1. parse dates
orders = []
with open("data/orders.csv") as f:
    for row in csv.DictReader(f):
        od = parse_date(row["order_date"])
        ua = datetime.fromisoformat(row["updated_at"])
        row["_order_date"] = od
        row["_updated_at"] = ua
        row["_amount"] = float(row["amount"])
        orders.append(row)

# 2. filter cancelled
orders = [o for o in orders if o["status"] != "cancelled"]

# 3. deduplicate latest by order_id (latest updated_at)
latest = {}
for o in orders:
    key = o["order_id"]
    if key not in latest or o["_updated_at"] > latest[key]["_updated_at"]:
        latest[key] = o
orders = list(latest.values())

# 4. join customers
cust_map = {}
with open("data/customers.json") as f:
    for c in json.load(f):
        cust_map[c["customer_id"]] = c
for o in orders:
    o["segment"] = cust_map[o["customer_id"]]["segment"]

# 5. apply adjustments
adj = {}
with open("data/adjustments.csv") as f:
    for row in csv.DictReader(f):
        adj[row["order_id"]] = float(row["adjustment"])
for o in orders:
    if o["order_id"] in adj:
        o["_amount"] += adj[o["order_id"]]

# group by month, segment
groups = defaultdict(lambda: {"order_count": 0, "total_amount": 0.0})
for o in orders:
    month = o["_order_date"].strftime("%Y-%m")
    g = groups[(month, o["segment"])]
    g["order_count"] += 1
    g["total_amount"] += o["_amount"]

result = []
for (month, segment), v in sorted(groups.items()):
    result.append({
        "month": month,
        "segment": segment,
        "order_count": v["order_count"],
        "total_amount": round(v["total_amount"], 2),
    })

os.makedirs("outputs", exist_ok=True)
with open("outputs/report.json", "w") as f:
    json.dump(result, f, indent=2)

print(json.dumps(result, indent=2))

