def stitch_fragments(rows: list[dict[str, object]]) -> list[dict[str, object]]:
    summary: dict[str, dict[str, object]] = {}
    for row in rows:
        # Cancelled jobs must be excluded from the merged report.
        if str(row.get("status", "")).lower() == "cancelled":
            continue
